{
  "schemaVersion": "0.2",
  "slug": "heatmap",
  "name": "Heatmap",
  "family": "F",
  "status": "experimental",
  "purpose": "Renders a matrix of values as color-intensity cells over a token-derived scale.",
  "scenarios": [
    "Commit activity calendar",
    "Hour-by-day traffic matrix",
    "Risk severity grid"
  ],
  "props": {
    "rows": {
      "type": "string",
      "required": true,
      "description": "Row labels in order."
    },
    "columns": {
      "type": "string",
      "required": true,
      "description": "Column labels in order."
    },
    "values": {
      "type": "string",
      "required": true,
      "description": "Row-major matrix of numbers matching rows x columns."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible description of the matrix."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Matrix rendered."
    },
    {
      "name": "empty",
      "description": "No values provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "page",
      "app-shell"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not rely on color alone; cells expose their numeric value.",
    "Do not render matrices larger than 60x24 without pagination."
  ],
  "a11y": {
    "role": "grid",
    "keyboard": [],
    "focus": "Cells are not focusable; values are available to screen readers via text.",
    "labeling": "aria-label summarizes the matrix; each cell exposes its value.",
    "wcag": [
      "1.1.1",
      "1.4.1"
    ]
  },
  "responsive": {
    "strategy": "Cells shrink to a minimum size; container scrolls horizontally beyond that.",
    "breakpoints": {
      "compact": "Horizontal scroll.",
      "medium": "Fit container.",
      "large": "Fit container."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "heatmap",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "visualize-data"
    ]
  }
}

import './styles.css'

export interface HeatmapProps {
  rows: string[]
  columns: string[]
  values: number[][]
  label: string
  className?: string
}

export function Heatmap({ rows, columns, values, label, className }: HeatmapProps) {
  const classes = ['cu-heatmap', className].filter(Boolean).join(' ')
  const flat = values.flat()
  const max = flat.length > 0 ? Math.max(...flat) : 0
  const empty = rows.length === 0 || columns.length === 0 || flat.length === 0

  return (
    <div className={classes} data-ai-role="heatmap" data-ai-intent="visualize-data" data-ai-state={empty ? 'empty' : 'default'}>
      <div
        className="cu-heatmap__grid"
        role="grid"
        aria-label={label}
        style={{
          // Cascades to header/body rows via grid-template-columns: var(--cu-heatmap-cols)
          ['--cu-heatmap-cols' as string]: `auto repeat(${Math.max(columns.length, 1)}, minmax(var(--cu-space-3), 1fr))`,
        }}
      >
        <div className="cu-heatmap__header-row" role="row">
          <span className="cu-heatmap__corner" role="columnheader">
            <span className="cu-heatmap__corner-sr">{label}</span>
          </span>
          {columns.map((column) => (
            <span key={column} className="cu-heatmap__column" role="columnheader">
              {column}
            </span>
          ))}
        </div>
        {rows.map((row, rowIndex) => (
          <div key={row} className="cu-heatmap__row-wrap" role="row">
            <span className="cu-heatmap__row" role="rowheader">
              {row}
            </span>
            {columns.map((column, columnIndex) => {
              const value = values[rowIndex]?.[columnIndex] ?? 0
              const intensity = max > 0 ? Math.round((value / max) * 90) : 0
              return (
                <span
                  key={`${row}-${column}`}
                  className="cu-heatmap__cell"
                  role="gridcell"
                  aria-label={`${row} ${column}: ${value}`}
                  style={{
                    background: `color-mix(in srgb, var(--cu-color-palette-brand) ${intensity}%, var(--cu-color-background-default))`,
                  }}
                >
                  <span className="cu-heatmap__value">{value}</span>
                </span>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

.cu-heatmap {
  display: block;
  overflow-x: auto;
  color: var(--cu-color-fg-default);
}

.cu-heatmap__grid {
  display: flex;
  flex-direction: column;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-heatmap__header-row,
.cu-heatmap__row-wrap {
  display: grid;
  grid-template-columns: var(--cu-heatmap-cols);
  align-items: center;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-heatmap__corner-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.cu-heatmap__corner {
  position: relative;
}

.cu-heatmap__row,
.cu-heatmap__column {
  font-size: 0.75em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
  padding-inline-end: var(--cu-space-1);
}

.cu-heatmap__cell {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-block-size: var(--cu-space-3);
  border-radius: calc(var(--cu-space-1) / 2);
  font-size: 0.625em;
  contain: layout style paint;
  content-visibility: auto;
  contain-intrinsic-size: 2.5rem 1.5rem;
}
